using Store;

namespace ShoppingCart.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private Store.ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new Store.ShoppingCart();
    }

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        Assert.AreEqual(19.98m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_SumsCorrectly()
    {
        _cart.AddItem("SKU-001", 1, 10m);
        _cart.AddItem("SKU-002", 3, 5m);

        Assert.AreEqual(25m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-001", 1, 10m);
        _cart.AddItem("SKU-001", 2, 10m);

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(null!, 1, 10m));
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU-001", 0, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU-001", 1, -5m));
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromTotal()
    {
        _cart.AddItem("SKU-001", 2, 10m);
        _cart.AddItem("SKU-002", 1, 5m);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(5m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(null!));
    }

    // --- CalculateTotal ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    [DataRow(1, 25.00, 25.00)]
    [DataRow(3, 9.99, 29.97)]
    [DataRow(10, 1.50, 15.00)]
    public void CalculateTotal_VariousQuantities_ReturnsCorrectTotal(
        int quantity, double price, double expectedTotal)
    {
        _cart.AddItem("SKU-001", quantity, (decimal)price);

        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    // --- ApplyCoupon ---

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF", 50.00)]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, double expectedTotal)
    {
        _cart.AddItem("SKU-001", 1, 100m);

        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_AppliesDiscount()
    {
        _cart.AddItem("SKU-001", 1, 100m);

        _cart.ApplyCoupon("save10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    public void ApplyCoupon_NullCode_ThrowsArgumentException()
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(null!));
    }

    [TestMethod]
    public void ApplyCoupon_AppliedAfterAddingItems_AffectsTotal()
    {
        _cart.AddItem("SKU-001", 2, 50m);
        _cart.AddItem("SKU-002", 1, 20m);

        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(96m, _cart.CalculateTotal());
    }
}

